('Bonifico a vs favore *COMUNE DI PATTI 2026-02560-000023543 CIG BC47583677 TINDARI FESTIVA L - 70 EDIZIONE - ANNO 2026 - ABUMANESIMO - L ESSERE, IL NON Info aggiuntive: Data ordine: 08/07/2026 Ragione sociale ordinante: COMUNE DI PATTI IBAN ordinante: IT10P0623082381000015222562 Indirizzo ordinante: PIAZZA SCAFFIDI, 1 98066 PATTI ID_BONIFICO: TE0623052399218805268238182381IT Descrizione aggiuntiva del movimento: *COMUNE DI PATTI 2026-02560-000023543 CIG BC47583677 TINDARI FESTIVA L - 70 EDIZIONE - ANNO 2026 - A Descrizione estesa del movimento: BUMANESIMO - L ESSERE, IL NON'::text, '2026-07-08'::date, 2500::numeric, 2.5::numeric)
),
upd AS (
  UPDATE movimenti_bancari m
  SET importo = c.importo_ok
  FROM corrections c
  WHERE m.data_movimento = c.data_movimento
    AND m.stato IN ('importato','matchato','assegnato')
    AND round(m.importo::numeric, 2) IS DISTINCT FROM round(c.importo_ok, 2)
    AND (
      m.descrizione = c.descrizione
      OR (
        left(m.descrizione, 90) = left(c.descrizione, 90)
        AND c.importo_v IS NOT NULL
        AND (
          round(m.importo::numeric, 2) = round(c.importo_v, 2)
          OR abs(m.importo - c.importo_ok * 100) < 0.05
          OR abs(m.importo * 1000 - c.importo_ok) < 0.05
        )
      )
    )
  RETURNING m.id
)
SELECT count(*)::int AS updated FROM upd;